// Package models holds the domain models of the order module.
//
// The types here are independent of the database driver: pgtype and the types
// generated by sqlc DO NOT LEAK in here. The translation is done in the
// repository layer; the service, the API and the tests see only these types.
//
// Money is an INTEGER minor unit everywhere (cents) and the currency stands in
// a separate field (plan Section 8); floating point is used in no field. Times
// are UTC.
package models

import "time"

// Amount and quantity limits.
//
// The limits are not arbitrary: a line subtotal is computed as unit price ×
// quantity and that product MUST FIT into int64. Because MaxAmount ×
// MaxQuantity = 10^12 × 10^6 = 10^18 < 9.22×10^18, overflow is structurally
// impossible. The same limits are deliberately identical to the limits in the
// cart and pricing modules; because the modules do not import one another the
// value is repeated here (the accepted price of ADR 0001).
const (
	// MinAmount is the smallest permitted amount. A negative amount is not a
	// discount; a discount is carried in a separate field (discount_total).
	MinAmount int64 = 0
	// MaxAmount is the largest permitted amount (minor unit).
	MaxAmount int64 = 1_000_000_000_000
	// MinQuantity is the smallest quantity of a line; a line with zero
	// quantity means the line is not there at all.
	MinQuantity int64 = 1
	// MaxQuantity is the largest quantity of a line.
	MaxQuantity int64 = 1_000_000
	// MaxTotal is the largest value of a TOTAL field (minor unit).
	//
	// The value is MaxAmount × MaxQuantity: the subtotal of a single line can
	// be at most this much, so it is the natural ceiling for the order totals
	// as well. The identity check (subtotal + tax_total + shipping_total)
	// produces at most 3 × 10^18 and fits into int64 (9.22 × 10^18); overflow
	// is structurally impossible.
	MaxTotal int64 = MaxAmount * MaxQuantity
)

// MinDisplayID is the smallest value of a valid order number.
//
// The number is produced by the database's IDENTITY column and the sequence
// starts at 1; a zero or negative number means the number was never produced
// (or was written by hand). That is why the value is not a threshold but a
// SANITY CHECK: see [ValidDisplayID].
const MinDisplayID int64 = 1

// ValidDisplayID reports whether an order number is usable.
//
// The order number is the only human readable key that is shown to the customer
// and searched for in a support record; a zero number would mean "an order with
// no number" and the customer would find it nowhere.
func ValidDisplayID(displayID int64) bool {
	return displayID >= MinDisplayID
}

// OrderStatus is where an order stands in its lifecycle.
type OrderStatus string

// Order statuses.
//
// The transitions are one-way and the two ends are TERMINAL:
//
//	pending -> completed -> archived
//	pending -> canceled
//
// There is NO exit from canceled and archived. Reopening a canceled order would
// assume that the stock released along with the cancellation and the refunded
// payment can be taken back; neither of the two is true. A new request is a new
// order.
const (
	// OrderPending means the order was taken; it is not completed yet.
	OrderPending OrderStatus = "pending"
	// OrderCompleted means the payment and delivery side of the order closed.
	OrderCompleted OrderStatus = "completed"
	// OrderArchived means the completed order was taken out of the daily
	// lists.
	OrderArchived OrderStatus = "archived"
	// OrderCanceled means the order was canceled; canceled_at is stamped.
	OrderCanceled OrderStatus = "canceled"
)

// Valid reports whether the status is a defined value.
func (s OrderStatus) Valid() bool {
	switch s {
	case OrderPending, OrderCompleted, OrderArchived, OrderCanceled:
		return true
	default:
		return false
	}
}

// String returns the textual representation of the status.
func (s OrderStatus) String() string {
	return string(s)
}

// Order is an order.
//
// # Immutability
//
// After an order is written its AMOUNTS and its LINES do not change: an order is
// the permanent answer to the question "what was sold at that moment and how
// much did it cost". The only thing that changes is [Order.Status] and the
// stamps tied to it. Corrections that arise afterwards are carried in separate
// records ([Return], [Exchange], [Claim]).
//
// # Identifiers of other modules
//
// RegionID, CustomerID, CartID and the VariantID on the lines are identifiers of
// other modules; they are stored as free text and NO FOREIGN KEY IS GIVEN
// (Principle 2.2). Their existence is not validated in this module — validating
// is the job of the workflow that knows those modules (ADR 0006).
type Order struct {
	// ID is the time-sortable identifier with the "order_" prefix.
	ID string
	// DisplayID is the human readable INCREASING number shown to the customer.
	//
	// Its value is NOT PRODUCED BY THE APPLICATION; the database's IDENTITY
	// column produces it. The reason is concurrency: "read the largest, add
	// one, write" would produce the same number for two concurrent orders (see
	// the migration comment).
	DisplayID int64
	// Status is where the order stands in its lifecycle.
	Status OrderStatus
	// RegionID is the order's region; it belongs to the region module and is
	// NOT A FOREIGN KEY. It is required.
	RegionID string
	// CustomerID is the customer who owns the order; when empty the order
	// belongs to a GUEST.
	CustomerID string
	// Email is the order's contact address; on a guest order it is the only way
	// to follow it.
	Email string
	// CurrencyCode is the ISO 4217 code and is always stored in UPPER case.
	CurrencyCode string
	// CartID is the cart the order was born from; it only documents the ORIGIN
	// and may be empty (e.g. an order opened by administration).
	CartID string
	// IdempotencyKey is the key that prevents the same order from being written
	// twice; it may be empty (see Principle 2.6).
	IdempotencyKey string
	// Subtotal is the sum of the line subtotals (minor unit).
	Subtotal int64
	// DiscountTotal is the total discount (minor unit); it is stored positive
	// and is SUBTRACTED from the total.
	DiscountTotal int64
	// TaxTotal is the total tax (minor unit).
	TaxTotal int64
	// ShippingTotal is the total shipping amount (minor unit).
	ShippingTotal int64
	// Total is the amount to be paid (minor unit):
	// Subtotal - DiscountTotal + TaxTotal + ShippingTotal.
	Total int64
	// Metadata is the caller's free-form extra data.
	Metadata map[string]any
	// PlacedAt is the moment the order was placed (UTC).
	PlacedAt time.Time
	// CompletedAt is the moment the order was completed; nil when it is not
	// completed.
	CompletedAt *time.Time
	// CanceledAt is the moment the order was canceled; nil when it is not
	// canceled.
	CanceledAt *time.Time
	// CancelReason is the cancellation rationale; it is empty on an order that
	// was not canceled.
	CancelReason string
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
	// DeletedAt is the moment of the soft delete; when nil the order is live.
	DeletedAt *time.Time
}

// Canceled reports whether the order has been canceled.
func (o Order) Canceled() bool {
	return o.Status == OrderCanceled
}

// Completed reports whether the order has been completed (or archived).
//
// An archived order is completed too: archiving takes the order out of the
// lists, it does not undo its completeness.
func (o Order) Completed() bool {
	return o.Status == OrderCompleted || o.Status == OrderArchived
}

// Guest reports whether the order belongs to a guest.
func (o Order) Guest() bool {
	return o.CustomerID == ""
}

// TotalsConsistent reports that the totals identity holds:
// Total = Subtotal - DiscountTotal + TaxTotal + ShippingTotal.
//
// The check exists both at the service entrance and in a database constraint;
// both force the same identity and prevent a calculation error in a saga step
// from being written onto the order silently.
func (o Order) TotalsConsistent() bool {
	return o.Total == o.Subtotal-o.DiscountTotal+o.TaxTotal+o.ShippingTotal
}

// DiscountWithinSubtotal reports that the discount does not exceed the subtotal.
//
// Had it exceeded, the customer would win back more than the goods they bought,
// and part of the tax and of the shipping would be covered by the discount.
func (o Order) DiscountWithinSubtotal() bool {
	return o.DiscountTotal <= o.Subtotal
}

// OrderDetail is the order in full, together with its children.
//
// The type being separate is deliberate: [Order] is a single row and the listing
// paths DO NOT RUN a child query (the N+1 ban). This type is the only place
// where the children are loaded, so the ambiguity "does this order have lines,
// or were they simply not loaded?" never arises.
type OrderDetail struct {
	// Order is the order itself.
	Order
	// Items are the order's lines; they are in creation order.
	Items []OrderLineItem
	// Summary is the order's payment/refund summary. Because the summary is
	// born together with the order it is always populated here.
	Summary OrderSummary
}

// OrderLineItem is one line on the order.
//
// Title and UnitPrice are COPIED from the cart: even if the catalog changes
// afterwards (or the variant is deleted) the name and the amount seen on the
// invoice do not change. VariantID is the identifier of another module (product)
// and is NOT A FOREIGN KEY (Principle 2.2).
type OrderLineItem struct {
	// ID is the identifier with the "oli_" prefix.
	ID string
	// OrderID is the order the line belongs to.
	OrderID string
	// VariantID is the product variant the line points at; it belongs to the
	// product module.
	VariantID string
	// Title is the displayed name of the line.
	Title string
	// Quantity is the quantity on the line; it is always positive.
	Quantity int64
	// UnitPrice is the unit price (minor unit).
	UnitPrice int64
	// Subtotal is the line's subtotal (minor unit).
	Subtotal int64
	// DiscountTotal is the discount falling on the line (minor unit); it is
	// stored positive.
	DiscountTotal int64
	// TaxTotal is the tax falling on the line (minor unit).
	TaxTotal int64
	// Total is the line's total (minor unit):
	// Subtotal - DiscountTotal + TaxTotal.
	Total int64
	// Metadata is the caller's free-form extra data.
	Metadata map[string]any
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
}

// TotalsConsistent reports that the line totals identity holds:
// Total = Subtotal - DiscountTotal + TaxTotal.
//
// There is no shipping at line level; shipping belongs to the whole order.
func (l OrderLineItem) TotalsConsistent() bool {
	return l.Total == l.Subtotal-l.DiscountTotal+l.TaxTotal
}

// DiscountWithinSubtotal reports that the line discount does not exceed the
// subtotal.
func (l OrderLineItem) DiscountWithinSubtotal() bool {
	return l.DiscountTotal <= l.Subtotal
}

// OrderSummary is the summary of the paid/refunded/outstanding amount of an
// order.
//
// There is a single record per order and it is born TOGETHER with the order,
// zeroed out; there is no such state as "an order without a summary".
//
// The outstanding amount IS NOT STORED, it is computed with
// [OrderSummary.Outstanding]: had it been stored, the mutual consistency of the
// three numbers would have to be protected by a separate constraint and a
// derived value would be able to go stale.
type OrderSummary struct {
	// ID is the identifier with the "osum_" prefix.
	ID string
	// OrderID is the order the summary belongs to.
	OrderID string
	// PaidTotal is the total amount COLLECTED against the order (minor unit).
	PaidTotal int64
	// RefundedTotal is the total amount PAID BACK to the customer (minor unit).
	RefundedTotal int64
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Outstanding returns the OUTSTANDING (not yet collected) amount of the order.
//
// The order total is taken as a parameter because the summary DOES NOT STORE it:
// keeping the same number in two tables would open a place where the two could
// diverge, and the sole owner of the order total is the orders table.
//
// The result may be NEGATIVE: if the collected amount exceeds the order total
// (overcollection) the difference is a debt to the customer. The value is not
// clamped to zero; clamping would make overcollection invisible.
func (s OrderSummary) Outstanding(orderTotal int64) int64 {
	return orderTotal - (s.PaidTotal - s.RefundedTotal)
}

// ReturnStatus is the status of a return record.
type ReturnStatus string

// Return statuses.
const (
	// ReturnRequested means the return was requested.
	ReturnRequested ReturnStatus = "requested"
	// ReturnReceived means the returned goods were received.
	ReturnReceived ReturnStatus = "received"
	// ReturnCanceled means the return request was canceled.
	ReturnCanceled ReturnStatus = "canceled"
)

// Valid reports whether the status is a defined value.
func (s ReturnStatus) Valid() bool {
	switch s {
	case ReturnRequested, ReturnReceived, ReturnCanceled:
		return true
	default:
		return false
	}
}

// String returns the textual representation of the status.
func (s ReturnStatus) String() string {
	return string(s)
}

// Return is a return record (plan Section 6).
//
// In Phase 6 it is a SKELETON: the record is kept and listed, but the return
// workflow (line-based return, taking the stock back, refunding the payment)
// belongs to later phases. That is why there is no line-based child record yet.
type Return struct {
	// ID is the identifier with the "ret_" prefix.
	ID string
	// OrderID is the order the return belongs to.
	OrderID string
	// Status is the status of the return.
	Status ReturnStatus
	// RefundAmount is the amount planned to be refunded (minor unit).
	RefundAmount int64
	// Reason is the rationale of the return.
	Reason string
	// Note is a free-form note.
	Note string
	// Metadata is the caller's free-form extra data.
	Metadata map[string]any
	// ReceivedAt is the moment the goods were received; nil when they were not
	// received.
	ReceivedAt *time.Time
	// CanceledAt is the moment the request was canceled; nil when it was not
	// canceled.
	CanceledAt *time.Time
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
}

// ExchangeStatus is the status of an exchange record.
type ExchangeStatus string

// Exchange statuses.
const (
	// ExchangeRequested means the exchange was requested.
	ExchangeRequested ExchangeStatus = "requested"
	// ExchangeCompleted means the exchange was completed.
	ExchangeCompleted ExchangeStatus = "completed"
	// ExchangeCanceled means the exchange request was canceled.
	ExchangeCanceled ExchangeStatus = "canceled"
)

// Valid reports whether the status is a defined value.
func (s ExchangeStatus) Valid() bool {
	switch s {
	case ExchangeRequested, ExchangeCompleted, ExchangeCanceled:
		return true
	default:
		return false
	}
}

// String returns the textual representation of the status.
func (s ExchangeStatus) String() string {
	return string(s)
}

// Exchange is an exchange record (plan Section 6).
//
// In Phase 6 it is a SKELETON; the exchange workflow belongs to later phases.
type Exchange struct {
	// ID is the identifier with the "exch_" prefix.
	ID string
	// OrderID is the order the exchange belongs to.
	OrderID string
	// Status is the status of the exchange.
	Status ExchangeStatus
	// DifferenceDue is the exchange difference (minor unit).
	//
	// IT MAY BE NEGATIVE and that is deliberate: when positive the difference
	// is collected from the customer, when negative it is paid to the customer.
	// The sign states the direction, not the scale; the value is still an
	// INTEGER minor unit.
	DifferenceDue int64
	// Note is a free-form note.
	Note string
	// Metadata is the caller's free-form extra data.
	Metadata map[string]any
	// CompletedAt is the moment the exchange was completed; nil when it was not
	// completed.
	CompletedAt *time.Time
	// CanceledAt is the moment the request was canceled; nil when it was not
	// canceled.
	CanceledAt *time.Time
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
}

// ClaimType states how a damage/shortage record will be settled.
type ClaimType string

// Claim record types.
const (
	// ClaimRefund means the claim is settled with a refund.
	ClaimRefund ClaimType = "refund"
	// ClaimReplace means the claim is settled with a new copy of the product.
	ClaimReplace ClaimType = "replace"
)

// Valid reports whether the type is a defined value.
func (t ClaimType) Valid() bool {
	switch t {
	case ClaimRefund, ClaimReplace:
		return true
	default:
		return false
	}
}

// String returns the textual representation of the type.
func (t ClaimType) String() string {
	return string(t)
}

// ClaimStatus is the status of a damage/shortage record.
type ClaimStatus string

// Claim record statuses.
const (
	// ClaimRequested means the claim was opened.
	ClaimRequested ClaimStatus = "requested"
	// ClaimCompleted means the claim was settled.
	ClaimCompleted ClaimStatus = "completed"
	// ClaimCanceled means the claim was canceled.
	ClaimCanceled ClaimStatus = "canceled"
)

// Valid reports whether the status is a defined value.
func (s ClaimStatus) Valid() bool {
	switch s {
	case ClaimRequested, ClaimCompleted, ClaimCanceled:
		return true
	default:
		return false
	}
}

// String returns the textual representation of the status.
func (s ClaimStatus) String() string {
	return string(s)
}

// Claim is a damage/shortage record (plan Section 6).
//
// In Phase 6 it is a SKELETON; the claim workflow belongs to later phases.
type Claim struct {
	// ID is the identifier with the "claim_" prefix.
	ID string
	// OrderID is the order the claim belongs to.
	OrderID string
	// Type is how the claim will be settled.
	Type ClaimType
	// Status is the status of the claim.
	Status ClaimStatus
	// RefundAmount is the amount to be refunded while Type is ClaimRefund
	// (minor unit).
	RefundAmount int64
	// Reason is the rationale of the claim.
	Reason string
	// Note is a free-form note.
	Note string
	// Metadata is the caller's free-form extra data.
	Metadata map[string]any
	// CompletedAt is the moment the claim was settled; nil when it was not
	// settled.
	CompletedAt *time.Time
	// CanceledAt is the moment the request was canceled; nil when it was not
	// canceled.
	CanceledAt *time.Time
	// CreatedAt and UpdatedAt are UTC.
	CreatedAt time.Time
	UpdatedAt time.Time
}
